/**
 * Mini Jobaria (Tipo Agua) — Versión Chibi / Cría compañera de dinosaurio.
 * Basado en el arte oficial de Dinosaur King:
 *   assets/dinos/arte/agua/jobaria_der.webp
 * Construido sobre la base anatómica de Mini Ampelosaurus (saurópodo compañero).
 *
 * Características anatómicas del Jobaria (Saurópodo primitivo del Sáhara):
 *   - Cuello alto, estilizado y curvado con gracia hacia adelante y arriba.
 *   - Piel completamente lisa de saurópodo (sin osteodermos ni espinas dorsales).
 *   - Cabeza abovedada característica con cresta frontal suave sobre las fosas nasales.
 *   - Lomo curvado con suave inclinación hacia las extremidades traseras.
 *   - Patitas columnares rechonchas cerradas en cúpula dentro del cuerpo (cero huecos).
 *   - Mandíbula inferior estilizada y articulada para rugir, con dientecitos de marfil.
 *   - Ojos grandes anime con iris azul celeste brillante, pupila profunda y destellos.
 *   - Proyección lateral de textura oficial con piel azul pizarra / acero,
 *     marmoleado ocre arena en el dorso y vientre crema claro continuo.
 *   - Esqueleto con piel deformable (M.pielConHuesos) y animaciones completas (Reposo, Caminar, Rugir).
 */
registrarMalla({
  id: "mini_jobaria",
  categoria: "mini dino",
  nombre: "Mini Jobaria (Agua)",
  icono: "🦕",
  origen: "assets/dinos/arte/agua/jobaria_der.webp",

  construir(M) {
    const g = new THREE.Group();
    const LADOS = [-1, 1];
    const L = (s) => (s > 0 ? "I" : "D");
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const grad = Math.PI / 180;
    const cr = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t
      + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);

    // ---------------- UTILIDADES GEOMÉTRICAS ----------------
    const suave = (a, b, x) => {
      const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
      return t * t * (3 - 2 * t);
    };

    function rejilla(pos, cols, rows, nombre) {
      const idx = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const a = r * (cols + 1) + c;
          const b = a + cols + 1;
          idx.push(a, b, a + 1, b, b + 1, a + 1);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
      geo.setIndex(idx);
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, cols, rows);
    }

    function bloque(x, y, z, rx, ry, rz, curva = 0.5, nombre = "Bloque", segA = 12, segB = 10) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const pos = [];
      for (let r = 0; r <= sH; r++) {
        const v = r / sH;
        const th = (v - 0.5) * Math.PI;
        const cTh = Math.cos(th);
        const sTh = Math.sin(th);
        const ryCurva = Math.pow(Math.abs(cTh), curva);
        const yN = ry * Math.sign(sTh) * Math.pow(Math.abs(sTh), curva);
        for (let c = 0; c <= sW; c++) {
          const u = c / sW;
          const fi = u * Math.PI * 2;
          const sFi = Math.sin(fi);
          const cFi = Math.cos(fi);
          const xN = rx * ryCurva * Math.sign(cFi) * Math.pow(Math.abs(cFi), curva);
          const zN = rz * ryCurva * Math.sign(sFi) * Math.pow(Math.abs(sFi), curva);
          pos.push(x + xN, y + yN, z + zN);
        }
      }
      return M.coserNormales(rejilla(pos, sW, sH, nombre));
    }

    function punta(camino, rBase, nombre = "Punta", segL = 10, segR = 8) {
      const c = M.curva(camino);
      const sL = M.seg(segL, 6);
      const sR = M.seg(segR, 6);
      const geo = new THREE.TubeGeometry(c, sL, 1, sR, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();
      for (let i = 0; i <= sL; i++) {
        const t = i / sL;
        c.getPointAt(t, P);
        const r = rBase * Math.pow(1 - t, 0.85);
        for (let j = 0; j <= sR; j++) {
          const k = i * (sR + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      return M.coserNormales(M.pieza(geo, nombre, sR, sL));
    }

    function almendra(rx, ry, rz, nombre = "Almendra", segA = 14, segB = 10) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const pos = [];
      for (let r = 0; r <= sH; r++) {
        const v = r / sH;
        const th = (v - 0.5) * Math.PI;
        const cTh = Math.cos(th);
        const sTh = Math.sin(th);
        const yN = ry * sTh;
        const ancho = cTh * (1 - 0.25 * Math.abs(sTh));
        for (let c = 0; c <= sW; c++) {
          const u = c / sW;
          const fi = u * Math.PI * 2;
          const sFi = Math.sin(fi);
          const cFi = Math.cos(fi);
          const xN = rx * ancho * cFi;
          const zN = rz * ancho * sFi;
          pos.push(xN, yN, zN);
        }
      }
      return M.coserNormales(rejilla(pos, sW, sH, nombre));
    }

    // ---------------- 1. ANATOMÍA Y EJE DE JOBARIA ----------------
    // Saurópodo con cuello estilizado alto y cabeza abovedada (assets/dinos/arte/agua/jobaria_der.webp)
    // [z, y, rw, rhA, rhB, p]
    const EJE = [
      [-0.73, 0.49, 0.000, 0.000, 0.000, 2.0],  // Punta de la colita cerrada curvada arriba
      [-0.69, 0.46, 0.032, 0.035, 0.032, 2.0],  // Cola distal
      [-0.56, 0.43, 0.065, 0.070, 0.065, 2.1],  // Cola media
      [-0.40, 0.43, 0.110, 0.120, 0.110, 2.2],  // Base de la cola
      [-0.24, 0.45, 0.185, 0.205, 0.195, 2.4],  // Cadera
      [-0.05, 0.45, 0.220, 0.235, 0.235, 2.5],  // Vientre rechoncho
      [ 0.12, 0.48, 0.210, 0.230, 0.225, 2.4],  // Pecho y hombros
      [ 0.25, 0.55, 0.155, 0.170, 0.155, 2.3],  // Base del cuello estilizado
      [ 0.36, 0.67, 0.120, 0.130, 0.120, 2.2],  // Cuello medio erguido
      [ 0.46, 0.79, 0.105, 0.115, 0.110, 2.2],  // Cuello superior
      [ 0.54, 0.86, 0.110, 0.118, 0.115, 2.3],  // Nuca
      [ 0.62, 0.87, 0.125, 0.118, 0.115, 2.4],  // Cráneo abovedado chibi (Jobaria)
      [ 0.69, 0.85, 0.105, 0.110, 0.100, 2.3],  // Frente del hocico
      [ 0.73, 0.83, 0.075, 0.080, 0.070, 2.2],  // Hocico redondeado
      [ 0.75, 0.82, 0.000, 0.000, 0.000, 2.0]   // Cierre hermético
    ];

    const ejeCurva = new THREE.CatmullRomCurve3(EJE.map(([z, y]) => V(0, y, z)), false, "centripetal");
    ejeCurva.arcLengthDivisions = 1200;
    const LARGO = ejeCurva.getLength();

    function seccion(u) {
      const f = ejeCurva.getUtoTmapping(u) * (EJE.length - 1);
      const i = Math.min(EJE.length - 2, Math.floor(f));
      const t = f - i;
      const a = EJE[Math.max(0, i - 1)];
      const b = EJE[i];
      const c = EJE[i + 1];
      const d = EJE[Math.min(EJE.length - 1, i + 2)];
      return [2, 3, 4, 5].map((j) => Math.max(0, cr(a[j], b[j], c[j], d[j], t)));
    }

    const X = V(1, 0, 0);
    function marcoEje(u) {
      const P = ejeCurva.getPointAt(u);
      const T = ejeCurva.getTangentAt(u);
      const ang = Math.atan2(T.y, T.z);
      const angSuave = ang * 0.28;
      const U = V(0, Math.cos(angSuave), -Math.sin(angSuave));
      return { P, T, U };
    }

    function uCercano(p, desde = 0, hasta = 1) {
      let mejor = desde;
      let dMin = Infinity;
      for (let k = 0; k <= 400; k++) {
        const u = desde + (hasta - desde) * (k / 400);
        const d = ejeCurva.getPointAt(u).distanceToSquared(p);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    const COLS = M.seg(72, 20);
    const FILAS = M.seg(360, 60);
    const cuerpo = (() => {
      const pos = [];
      for (let r = 0; r <= FILAS; r++) {
        const u = r / FILAS;
        const { P, U } = marcoEje(u);
        const [w, hA, hB, p] = seccion(u);
        const ex = 2 / p;
        const z = P.z;

        const hombro = 0.045 * Math.exp(-Math.pow((z - 0.12) / 0.18, 2));
        const muslo = 0.045 * Math.exp(-Math.pow((z + 0.24) / 0.18, 2));

        for (let c = 0; c <= COLS; c++) {
          const fi = Math.PI + (c / COLS) * Math.PI * 2;
          const s = Math.sin(fi);
          const co = Math.cos(fi);
          const musculo = (hombro + muslo) * Math.pow(Math.abs(s), 1.6);
          const lx = (w + musculo) * Math.sign(s) * Math.pow(Math.abs(s), ex);
          const ly = ((co >= 0 ? hA : hB) + musculo * 0.4) * Math.sign(co) * Math.pow(Math.abs(co), ex);
          const pto = P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
          pos.push(pto.x, pto.y, pto.z);
        }
      }
      return M.coserNormales(rejilla(pos, COLS, FILAS, "CuerpoJobaria"));
    })();

    // ---------------- 2. ESQUELETO Y RIGGING ----------------
    const MANO_X = 0.175;
    const PIE_X = 0.170;

    const HUESOS = [
      ["Raiz", null, 0, 0, 0],
      ["Cadera", "Raiz", 0, 0.45, -0.24],
      ["Cola1", "Cadera", 0, 0.44, -0.40],
      ["Cola2", "Cola1", 0, 0.44, -0.56],
      ["Cola3", "Cola2", 0, 0.48, -0.69],
      ["Pecho", "Cadera", 0, 0.48, 0.12],
      ["Cuello1", "Pecho", 0, 0.58, 0.28],
      ["Cuello2", "Cuello1", 0, 0.74, 0.42],
      ["Cabeza", "Cuello2", 0, 0.87, 0.60],
      ["Mandibula", "Cabeza", 0, 0.80, 0.58],

      ["BrazoI", "Pecho", MANO_X, 0.46, 0.18],
      ["AntebrazoI", "BrazoI", MANO_X, 0.25, 0.18],
      ["ManoI", "AntebrazoI", MANO_X, 0.08, 0.18],

      ["BrazoD", "Pecho", -MANO_X, 0.46, 0.18],
      ["AntebrazoD", "BrazoD", -MANO_X, 0.25, 0.18],
      ["ManoD", "AntebrazoD", -MANO_X, 0.08, 0.18],

      ["MusloI", "Cadera", PIE_X, 0.44, -0.22],
      ["PiernaI", "MusloI", PIE_X, 0.23, -0.22],
      ["PieI", "PiernaI", PIE_X, 0.08, -0.22],

      ["MusloD", "Cadera", -PIE_X, 0.44, -0.22],
      ["PiernaD", "MusloD", -PIE_X, 0.23, -0.22],
      ["PieD", "PiernaD", -PIE_X, 0.08, -0.22]
    ];

    const hueso = {};
    HUESOS.forEach(([nombre, padre, x, y, z]) => {
      const b = new THREE.Bone();
      b.name = "Hueso" + nombre;
      b.userData.reposo = V(x, y, z);
      const p = padre ? hueso[padre] : null;
      b.position.set(x, y, z).sub(p ? p.userData.reposo : V(0, 0, 0));
      (p || g).add(b);
      hueso[nombre] = b;
    });
    g.updateMatrixWorld(true);

    const colgar = (nombre, obj) => {
      const h = typeof nombre === "string" ? hueso[nombre] : nombre;
      if (!h || !obj) return obj;
      h.attach(obj);
      return obj;
    };

    const uH = (n, d1 = 0.2, d2 = 1) => uCercano(hueso[n].userData.reposo, d1, d2);
    const uCola3 = uCercano(hueso.Cola3.userData.reposo, 0, 0.35);
    const uCola2 = uCercano(hueso.Cola2.userData.reposo, 0.1, 0.45);

    const TRAMOS = [
      [0, "Cola3"],
      [uCola3, "Cola2"],
      [uCola2, "Cola1"],
      [uH("Cola1", 0.15, 0.5), "Cadera"],
      [uH("Pecho", 0.35, 0.65), "Pecho"],
      [uH("Cuello1", 0.45, 0.75), "Cuello1"],
      [uH("Cuello2", 0.60, 0.85), "Cuello2"],
      [uH("Cabeza", 0.70, 0.95), "Cabeza"]
    ];

    const MEZCLA = 0.20 / LARGO;
    function pesosTramos(u, tramos, mezcla) {
      let k = 0;
      while (k + 1 < tramos.length && u >= tramos[k + 1][0]) k++;
      const res = [[hueso[tramos[k][1]], 1]];
      if (k + 1 < tramos.length) {
        const w = suave(-mezcla, mezcla, u - tramos[k + 1][0]);
        if (w > 0) { res[0][1] = 1 - w; res.push([hueso[tramos[k + 1][1]], w]); }
      }
      if (k > 0) {
        const w = 1 - suave(-mezcla, mezcla, u - tramos[k][0]);
        if (w > 0) { res[0][1] *= 1 - w; res.push([hueso[tramos[k - 1][1]], w]); }
      }
      return res;
    }

    g.add(cuerpo);
    M.pielConHuesos(cuerpo, g, (i) => pesosTramos(Math.floor(i / (COLS + 1)) / FILAS, TRAMOS, MEZCLA));

    // ---------------- 3. PATAS RECHONCHAS CERRADAS (CERO PIEZAS ABIERTAS) ----------------
    function pataCerrada(s, camino, radios, huesosPata, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(20, 8);
      const rSeg = M.seg(24, 10);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let r = M.interp(radios, t);
        if (t < 0.22) {
          r *= Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.22, 2)));
        }
        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      g.add(malla);

      const tramos = [
        [0, huesosPata[0]],
        [0.45, huesosPata[1]],
        [0.80, huesosPata[2]]
      ];
      M.pielConHuesos(malla, g, (i) => pesosTramos(Math.floor(i / (rSeg + 1)) / tSeg, tramos, 0.22));
      return malla;
    }

    LADOS.forEach((s) => {
      const xM = s * MANO_X;
      pataCerrada(s,
        [[xM * 0.92, 0.50, 0.18], [xM, 0.42, 0.18], [xM, 0.26, 0.18], [xM, 0.14, 0.18], [xM, 0.05, 0.18]],
        [[0, 0.112], [0.25, 0.102], [0.55, 0.086], [0.80, 0.080], [1, 0.075]],
        ["Brazo" + L(s), "Antebrazo" + L(s), "Mano" + L(s)], "PataDelantera");

      colgar("Mano" + L(s), bloque(xM, 0.045, 0.18, 0.068, 0.038, 0.066, 0.8, "PieDelantero"));

      // Pequeñas pezuñas / garras frontales de saurópodo
      [-0.030, 0.0, 0.030].forEach((dx, idx) => {
        const cPunta = [
          [xM + dx, 0.038, 0.22],
          [xM + dx * 1.05, 0.022, 0.245],
          [xM + dx * 1.10, 0.005, 0.260]
        ];
        colgar("Mano" + L(s), punta(cPunta, 0.010 - idx * 0.001, "GarraMano", 8, 6));
      });

      const xP = s * PIE_X;
      pataCerrada(s,
        [[xP * 0.92, 0.46, -0.22], [xP, 0.40, -0.22], [xP, 0.24, -0.22], [xP, 0.13, -0.22], [xP, 0.05, -0.22]],
        [[0, 0.115], [0.25, 0.105], [0.55, 0.090], [0.80, 0.084], [1, 0.078]],
        ["Muslo" + L(s), "Pierna" + L(s), "Pie" + L(s)], "PataTrasera");

      colgar("Pie" + L(s), bloque(xP, 0.045, -0.22, 0.072, 0.038, 0.070, 0.8, "PieTrasero"));

      // Pezuñas posteriores
      [-0.032, 0.0, 0.032].forEach((dx, idx) => {
        const cPunta = [
          [xP + dx, 0.038, -0.18],
          [xP + dx * 1.05, 0.022, -0.155],
          [xP + dx * 1.10, 0.005, -0.140]
        ];
        colgar("Pie" + L(s), punta(cPunta, 0.011 - idx * 0.001, "GarraPie", 8, 6));
      });
    });

    // ---------------- 4. CABEZA ABOVEDADA, MANDÍBULA Y DETALLES FACIALES ----------------
    // Arco frontal / cresta nasal convexa típica del Jobaria
    colgar("Cabeza", bloque(0, 0.900, 0.64, 0.065, 0.038, 0.075, 0.6, "ArcoNasal", 12, 10));

    // Mandíbula inferior estilizada
    const colsMand = M.seg(48, 20);
    const filasMand = M.seg(32, 16);
    const MAND_PERFIL = [
      [0.56, 0.820, 0.105, 0.026, 2.2],
      [0.62, 0.815, 0.100, 0.024, 2.2],
      [0.68, 0.805, 0.085, 0.022, 2.2],
      [0.72, 0.795, 0.055, 0.018, 2.1],
      [0.74, 0.790, 0.000, 0.000, 2.0]
    ];

    const posMand = [];
    for (let r = 0; r <= filasMand; r++) {
      const u = r / filasMand;
      const f = u * (MAND_PERFIL.length - 1);
      const i = Math.min(MAND_PERFIL.length - 2, Math.floor(f));
      const k = f - i;
      const a = MAND_PERFIL[Math.max(0, i - 1)];
      const b = MAND_PERFIL[i];
      const c = MAND_PERFIL[i + 1];
      const d = MAND_PERFIL[Math.min(MAND_PERFIL.length - 1, i + 2)];
      const [z, y, w, h, p] = [0, 1, 2, 3, 4].map((j) => cr(a[j], b[j], c[j], d[j], k));
      const ex = 2 / p;

      for (let col = 0; col <= colsMand; col++) {
        const fi = Math.PI + (col / colsMand) * Math.PI * 2;
        const s = Math.sin(fi);
        const co = Math.cos(fi);
        const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
        const ly = h * Math.sign(co) * Math.pow(Math.abs(co), ex);
        posMand.push(lx, y + ly, z);
      }
    }

    colgar("Mandibula", M.coserNormales(rejilla(posMand, colsMand, filasMand, "MandibulaJobaria")));
    colgar("Mandibula", bloque(0, 0.810, 0.64, 0.048, 0.012, 0.070, 0.6, "Lengua"));

    LADOS.forEach((s) => {
      [0.61, 0.66, 0.71].forEach((z, idx) => {
        const wTeeth = 0.095 - idx * 0.016;
        const xTeeth = s * wTeeth;
        colgar("Mandibula", punta([[xTeeth, 0.812, z], [xTeeth, 0.826, z + 0.002]], 0.005, "DienteInferior", 8, 6));
      });

      [0.62, 0.67, 0.72].forEach((z, idx) => {
        const wTeeth = 0.102 - idx * 0.016;
        const xTeeth = s * wTeeth;
        colgar("Cabeza", punta([[xTeeth, 0.835, z], [xTeeth, 0.820, z + 0.002]], 0.0055, "DienteSuperior", 8, 6));
      });

      const labioPuntos = [
        [s * 0.112, 0.840, 0.58],
        [s * 0.102, 0.836, 0.63],
        [s * 0.088, 0.830, 0.68],
        [s * 0.060, 0.824, 0.72],
        [s * 0.008, 0.820, 0.74]
      ];
      colgar("Cabeza", M.tubo(labioPuntos, 0.0055, 0.004, { segLargo: 24, segRadio: 10, nombre: "LabioSuperior" }));
    });

    // Fosas nasales en la zona anterior elevada
    LADOS.forEach((s) => {
      colgar("Cabeza", bloque(s * 0.035, 0.865, 0.71, 0.008, 0.006, 0.010, 0.4, "FosaNasal", 10, 8));
    });

    // Ojos grandes anime con iris celeste aguamarina
    LADOS.forEach((s) => {
      const ojoGrupo = new THREE.Group();
      ojoGrupo.position.set(s * 0.118, 0.885, 0.635);
      ojoGrupo.rotation.y = s * 0.35;

      ojoGrupo.add(almendra(0.044, 0.038, 0.014, "OjoBlanco"));
      ojoGrupo.add(bloque(s * 0.004, 0, 0.005, 0.030, 0.030, 0.008, 1, "IrisAgua"));
      ojoGrupo.add(bloque(s * 0.004, -0.002, 0.010, 0.017, 0.019, 0.006, 1, "Pupila"));
      ojoGrupo.add(bloque(-s * 0.010, 0.012, 0.014, 0.011, 0.011, 0.005, 1, "BrilloOjo"));
      ojoGrupo.add(bloque(s * 0.010, -0.010, 0.013, 0.006, 0.006, 0.004, 1, "BrilloOjoPequeno"));

      ojoGrupo.add(M.tubo([
        [-0.038, 0.005, 0.006],
        [0, 0.036, 0.011],
        [0.038, 0.005, 0.006]
      ], 0.005, 0.004, { segLargo: 10, segRadio: 8, nombre: "ParpadoSuperior" }));

      ojoGrupo.add(M.tubo([
        [-0.035, -0.005, 0.006],
        [0, -0.034, 0.009],
        [0.035, -0.005, 0.006]
      ], 0.0045, 0.0035, { segLargo: 10, segRadio: 8, nombre: "ParpadoInferior" }));

      colgar("Cabeza", ojoGrupo);
    });

    // ---------------- 5. PINTURA: PROYECCIÓN Y COLORES DE JOBARIA_DER.WEBP ----------------
    const TEXTURA = this.textura;
    const proyectar = M.proyeccion(TEXTURA, 1.05);

    const C_SLATE_BASE = new THREE.Color(0x3e526c);
    const C_CREMA_VIENTRE = new THREE.Color(0xf4f7fa);
    const C_LENGUA = new THREE.Color(0xdf6f78);
    const C_TAN_FACE = new THREE.Color(0xd8caa8);
    const MARFIL = new THREE.Color(0xede5ce);
    const cColor = new THREE.Color();

    M.pintar(cuerpo, (i, p) => {
      proyectar(p.z, p.y, cColor);

      if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) {
        cColor.copy(C_SLATE_BASE);
      }

      // Vientre y garganta más claros continuos en la parte inferior
      const u = Math.floor(i / (COLS + 1)) / FILAS;
      const cIdx = i % (COLS + 1);
      const fi = Math.PI + (cIdx / COLS) * Math.PI * 2;
      const co = Math.cos(fi);

      if (co < 0 && p.y < 0.75 && u > 0.14 && u < 0.92) {
        const factorVientre = Math.pow(-co, 1.4) * suave(0.75, 0.40, p.y);
        cColor.lerp(C_CREMA_VIENTRE, Math.min(1, factorVientre * 0.92));
      }

      return cColor;
    }, g);

    const COLOR_PIEZAS = {
      pataDelantera: 0x425670,
      pataTrasera: 0x384a5f,
      mandibula: 0x3a4c62,
      labio: 0x2c3b4e,
      fosaNasal: 0x1f2b38,
      parpado: 0x36485c,
      iris: 0x38bdf8,
      pupila: 0x091b26,
      brillo: 0xffffff,
      ojoBlanco: 0xfefcf9
    };

    const piezas = [];
    g.traverse((o) => { if (o.isMesh && o !== cuerpo) piezas.push(o); });

    piezas.forEach((o) => {
      if (/^(Diente|Garra)/.test(o.name)) return M.pintar(o, () => MARFIL, g);
      if (o.name === "ArcoNasal") return M.pintar(o, () => C_TAN_FACE, g);
      if (o.name === "Lengua") return M.pintar(o, () => C_LENGUA, g);
      if (o.name === "OjoBlanco") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.ojoBlanco), g);
      if (o.name === "IrisAgua") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.iris), g);
      if (o.name === "Pupila") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.pupila), g);
      if (/^BrilloOjo/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.brillo), g);
      if (/^Parpado/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.parpado), g);
      if (o.name === "LabioSuperior") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.labio), g);
      if (o.name === "FosaNasal") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.fosaNasal), g);

      if (o.name === "MandibulaJobaria") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, p.y, cColor);
          if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.setHex(COLOR_PIEZAS.mandibula);
          return cColor;
        }, g);
      }

      if (o.name === "PataDelantera" || o.name === "PieDelantero") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, Math.max(p.y, 0.18), cColor);
          if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.setHex(COLOR_PIEZAS.pataDelantera);
          return cColor;
        }, g);
      }

      if (o.name === "PataTrasera" || o.name === "PieTrasero") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, Math.max(p.y, 0.18), cColor);
          if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.setHex(COLOR_PIEZAS.pataTrasera);
          return cColor;
        }, g);
      }

      M.pintar(o, (i, p) => {
        proyectar(p.z, p.y, cColor);
        if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) {
          cColor.copy(C_SLATE_BASE);
        }
        return cColor;
      }, g);
    });

    // ---------------- 6. ANIMACIONES COMPLEMENTARIAS ----------------
    function giro(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const q = new THREE.Quaternion();
      const eu = new THREE.Euler(0, 0, 0, "YXZ");
      for (let i = 0; i <= n; i++) {
        const [x, y, z] = fn(i / n);
        eu.set(x * grad, y * grad, z * grad);
        q.setFromEuler(eu);
        tiempos.push(i * (dur / n));
        valores.push(q.x, q.y, q.z, q.w);
      }
      return new THREE.QuaternionKeyframeTrack("Hueso" + nombre + ".quaternion", tiempos, valores);
    }

    function sube(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const [x0, y0, z0] = hueso[nombre].position.toArray();
      for (let i = 0; i <= n; i++) {
        tiempos.push(i * (dur / n));
        valores.push(x0, y0 + fn(i / n), z0);
      }
      return new THREE.VectorKeyframeTrack("Hueso" + nombre + ".position", tiempos, valores);
    }

    const sen = (t, c = 1) => Math.sin(t * Math.PI * 2 * c);
    const cos = (t, c = 1) => Math.cos(t * Math.PI * 2 * c);

    const dR = 3.6;
    const reposo = new THREE.AnimationClip("Reposo", dR, [
      sube("Cadera", dR, (t) => 0.008 * sen(t)),
      giro("Pecho", dR, (t) => [1.2 * sen(t), 0, 0]),
      giro("Cuello1", dR, (t) => [-1.8 * sen(t), 0, 0]),
      giro("Cuello2", dR, (t) => [2.2 * sen(t), 1.5 * cos(t), 0]),
      giro("Cabeza", dR, (t) => [-1.5 * sen(t), 2.0 * cos(t), 1.0 * sen(t)]),
      giro("Cola1", dR, (t) => [1.0 * sen(t), 3.0 * sen(t), 0]),
      giro("Cola2", dR, (t) => [1.5 * sen(t), 5.0 * sen(t), 0]),
      giro("Cola3", dR, (t) => [2.0 * sen(t), 7.0 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dR, (t) => [-1.0 * sen(t), 0, 0]),
        giro("Muslo" + L(s), dR, (t) => [1.0 * sen(t), 0, 0])
      ])
    ]);

    const dC = 2.4;
    const PASO = 18;
    const caminar = new THREE.AnimationClip("Caminar", dC, [
      sube("Cadera", dC, (t) => 0.015 * sen(t, 2)),
      giro("Cadera", dC, (t) => [1.5 * sen(t, 2), 3 * sen(t), 0]),
      giro("Pecho", dC, (t) => [-1.5 * sen(t, 2), -3 * sen(t), 0]),
      giro("Cuello1", dC, (t) => [2.5 * sen(t, 2), 2 * sen(t), 0]),
      giro("Cuello2", dC, (t) => [-2.0 * sen(t, 2), 3 * sen(t), 0]),
      giro("Cabeza", dC, (t) => [2.0 * sen(t, 2), 2 * sen(t), 0]),
      giro("Cola1", dC, (t) => [1.0 * sen(t, 2), -5 * sen(t), 0]),
      giro("Cola2", dC, (t) => [1.5 * sen(t, 2), -9 * sen(t), 0]),
      giro("Cola3", dC, (t) => [2.0 * sen(t, 2), -14 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dC, (t) => [s * PASO * sen(t), 0, 0]),
        giro("Antebrazo" + L(s), dC, (t) => [s * Math.max(0, -PASO * 0.7 * sen(t)), 0, 0]),
        giro("Muslo" + L(s), dC, (t) => [s * -PASO * sen(t), 0, 0]),
        giro("Pierna" + L(s), dC, (t) => [s * Math.max(0, PASO * 0.7 * sen(t)), 0, 0])
      ])
    ]);

    const dG = 2.0;
    const alzar = [[0, 0], [0.25, 1], [0.75, 1], [1, 0]];
    const abrirBoca = [[0, 0], [0.25, 0], [0.42, 1], [0.72, 1], [0.88, 0], [1, 0]];
    const rugir = new THREE.AnimationClip("Rugir", dG, [
      sube("Cadera", dG, (t) => 0.040 * M.interp(alzar, t)),
      giro("Cadera", dG, (t) => [-12 * M.interp(alzar, t), 0, 0]),
      giro("Pecho", dG, (t) => [-16 * M.interp(alzar, t), 0, 0]),
      giro("Cuello1", dG, (t) => [14 * M.interp(alzar, t), 0, 0]),
      giro("Cuello2", dG, (t) => [18 * M.interp(alzar, t), 0, 0]),
      giro("Cabeza", dG, (t) => [12 * M.interp(alzar, t), 0, 0]),
      giro("Mandibula", dG, (t) => [26 * M.interp(abrirBoca, t), 0, 0]),
      giro("Cola1", dG, (t) => [4 * M.interp(alzar, t), 8 * sen(t, 2), 0]),
      giro("Cola2", dG, (t) => [6 * M.interp(alzar, t), 16 * sen(t, 2), 0]),
      giro("Cola3", dG, (t) => [8 * M.interp(alzar, t), 24 * sen(t, 2), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dG, (t) => [-22 * M.interp(alzar, t), 0, s * 6]),
        giro("Muslo" + L(s), dG, (t) => [10 * M.interp(alzar, t), 0, 0])
      ])
    ]);

    g.animations = [reposo, caminar, rugir];
    hueso.Raiz.userData.esqueleto = HUESOS.map(([nombre]) => "Hueso" + nombre);

    return g;
  },

  textura: {
    w: 260, h: 172, k: 2, esc: 0.00290, x0: 255, y0: 343,
    datos: ""
  }
});
